function checkRecord(n) {
  const MOD = 1e9 + 7;
  // dp[a][l]: records so far with a absences and a run of l 'L's at the end.
  let dp = [[1, 0, 0], [0, 0, 0]];
  for (let day = 0; day < n; day++) {
    const next = [[0, 0, 0], [0, 0, 0]];
    for (let a = 0; a <= 1; a++) {
      for (let l = 0; l <= 2; l++) {
        const count = dp[a][l];
        next[a][0] = (next[a][0] + count) % MOD;
        if (a === 0) {
          next[1][0] = (next[1][0] + count) % MOD;
        }
        if (l < 2) {
          next[a][l + 1] = (next[a][l + 1] + count) % MOD;
        }
      }
    }
    dp = next;
  }
  let total = 0;
  for (let a = 0; a <= 1; a++) {
    for (let l = 0; l <= 2; l++) {
      total = (total + dp[a][l]) % MOD;
    }
  }
  return total;
}

