function checkRecord(n) {
  // Split on where the single 'A' goes. ok[k] counts strings of P and L of length k with no "LLL":
  // they end in P, LP or LLP after a shorter valid string, which gives a tribonacci-like rule.
  const M = 1000000007n;
  const ok = [1n, 2n, 4n];
  for (let k = 3; k <= n; k++) ok.push((ok[k - 1] + ok[k - 2] + ok[k - 3]) % M);
  let total = ok[n];
  for (let i = 0; i < n; i++) total = (total + ok[i] * ok[n - 1 - i]) % M;
  return Number(total);
}

